// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address admin, bool access) public {
        vm.assume(admin != address(0));
        // Adjust admin access to ensure isAdmin[admin] is set
        c.adjustAdminAccess(admin, access);

        bytes4 interfaceId = type(IERC1155).interfaceId;
        bool result = c.supportsInterface(interfaceId);

        // The general rule: supportsInterface(IERC1155) should return true regardless of admin/access
        assertTrue(result, "supportsInterface should return true for IERC1155");
    }
}

