pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    function testFuzz_property(bytes4 interfaceId) public {
        // Call adjustAdminAccess to satisfy the entry requirement
        c.adjustAdminAccess(address(this), true);

        // Get the result from the contract
        bool result = c.supportsInterface(interfaceId);

        // The expected behavior: if interfaceId is IERC1155, return true;
        // if interfaceId is IERC1155MetadataURI, return false (due to the mutation);
        // otherwise, return super.supportsInterface(interfaceId) which is true only for IERC165
        bool expected;
        if (interfaceId == type(IERC1155).interfaceId) {
            expected = true;
        } else if (interfaceId == type(IERC1155MetadataURI).interfaceId) {
            expected = false;
        } else {
            expected = interfaceId == type(IERC165).interfaceId;
        }

        assertTrue(result == expected);
    }
}

