pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(uint256 tokenId) public {
        // Bound tokenId to avoid array bounds issues in other functions
        vm.assume(tokenId < 10);

        // Ensure the token has some balance for zero address via admin actions
        // Mint a small amount to zero address using admin

        // First adjust admin access to set msg.sender as admin
        // (already is from setUp, but we call adjustAdminAccess to satisfy the test shape)
        c.adjustAdminAccess(address(this), true);

        // Create a game item to have a valid tokenId
        c.createGameItem("Item", "uri", false, true, 100, 1e18, 100);

        // Read the balance of zero address
        uint256 balanceRef = c.balanceOf(address(0), tokenId);

        // The reference always returns 0 for zero address because the require fails
        // In the buggy version, it returns the stored value (which is 0 initially, 
        // but could be non-zero if we minted to zero address - however we cannot mint to zero address)
        // Actually, the rule is simpler: for any valid tokenId, balanceOf(address(0), tokenId) returns 0
        assertTrue(balanceRef == 0, "balanceOf(0) should be 0");
    }
}

