pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address account, uint256 tokenId) public {
        vm.assume(account != address(0));
        vm.assume(tokenId < 100); // bound to avoid overflow in internal mappings
        uint256 balanceZero = c.balanceOf(address(0), tokenId);
        uint256 balanceAccount = c.balanceOf(account, tokenId);
        // In the reference, both are 0 (no mints). In the bug, address(0) may return a stale value.
        // But a general rule: for any token id, balanceOf(address(0), id) equals balanceOf(address(1), id) when mint hasn't occurred?
        // Actually simpler: assert that balanceOf(account, tokenId) >= balanceOf(address(0), tokenId) - but that's not general.
        // The reference reverts for address(0) — so we must call balanceOf separately and catch the revert.
        // Let's restructure: state that for any account != address(0), the difference between balances is symmetric.
        // Use a simpler rule: balanceOf(address(0), tokenId) should revert, while for non-zero it shouldn't.
        // But the bug makes balanceOf(address(0)) not revert. So we can use the revert difference itself.
        bool zeroReverted;
        try c.balanceOf(address(0), tokenId) {
            zeroReverted = false;
        } catch {
            zeroReverted = true;
        }
        bool nonZeroReverted;
        try c.balanceOf(account, tokenId) {
            nonZeroReverted = false;
        } catch {
            nonZeroReverted = true;
        }
        // The reference: zeroReverted == true, nonZeroReverted == false (assuming account valid). Bug: zeroReverted == false also.
        // So property: balanceOf(address(0)) always reverts.
        assertTrue(zeroReverted);
    }
}

