pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    function testFuzz_property(address[] memory accounts, uint256[] memory ids) public {
        // Bound inputs to avoid excessive gas, but keep them realistic
        vm.assume(accounts.length <= 10 && ids.length <= 10);

        // Ensure that the original contract's require passes; buggy contract will not revert
        vm.assume(accounts.length == ids.length);

        // Get the result from balanceOfBatch
        uint256[] memory result = c.balanceOfBatch(accounts, ids);

        // The returned array length must equal accounts.length (reference behavior)
        // Buggy version would also return length = accounts.length, but might compute wrong values
        // Instead, we check a stronger property: for each i, balanceOf(accounts[i], ids[i]) == result[i]
        // This holds in reference but fails in mutant when accounts and ids have different lengths
        // (but we've assumed equal lengths above, so we need a different approach)

        // Actually, with equal lengths, both reference and mutant produce same result.
        // We need to test the case where lengths differ: reference reverts, mutant does not.
        // Let's remove the equal-length assumption and use try/catch.
        // Reset the assumption... We can't undo, so we need a different test.
    }

    function testFuzz_property_different_lengths(address[] memory accounts, uint256[] memory ids) public {
        vm.assume(accounts.length != ids.length);
        vm.assume(accounts.length <= 10 && ids.length <= 10);

        // In reference, this should revert; in mutant, it should not revert
        // We check this by calling balanceOfBatch and seeing if it reverts or not

        // However, we cannot directly detect revert from a view function in Solidity without low-level calls.
        // We'll use a different approach: compare the behavior of two calls.

        // Actually, using try/catch on a view function is not straightforward in Foundry.
        // Let's instead check that the returned array length equals accounts.length (buggy version does this)
        // and that the balances computed are consistent only when lengths match.

        // Given the constraint that we must use adjustAdminAccess, let's design a test that
        // demonstrates the bug via the public getters.

        // The bug is that balanceOfBatch doesn't revert when lengths differ, and the loop
        // accesses ids[i] for i up to accounts.length, causing out-of-bounds or wrong values.
        // This leads to the returned array having length = accounts.length but potentially
        // incorrect balance values for elements where i >= ids.length (out-of-bounds access would revert).

        // Since the mutant with ids.length == ids.length always passes, and the loop uses accounts.length,
        // if accounts.length > ids.length, it will revert on out-of-bounds. So the only non-reverting
        // difference is when accounts.length < ids.length: reference reverts, mutant does not.

        vm.assume(accounts.length < ids.length);

        // The reference would revert, but we can't catch that easily in a view function.
        // Instead, we use a low-level call to check.

        (bool refReverted, bytes memory refResult) = address(c).staticcall(
            abi.encodeWithSignature("balanceOfBatch(address[],uint256[])", accounts, ids)
        );

        // The reference should revert; the buggy version should not
        // But we can only test one version. So we check a property on the return value when the call succeeds.
        // Actually, we need to check that in the reference, the call reverts (so refReverted is true).
        // In the buggy version, refReverted is false and the returned array length equals accounts.length.

        // Since we can only run one version, we check that the length property holds when the call succeeds.
        // If the call reverts, the test automatically fails because we can't decode.
        // 
        // Better: assert that the call does NOT revert (which holds for buggy version but not reference).
        // But we need a general rule, not a per-version check.

        // The general rule: For all inputs, balanceOfBatch does not revert.
        // Reference violates this when accounts.length != ids.length.
        // Buggy version satisfies this for all inputs (since the require always passes).
        // So we assert that the call does not revert, which holds for buggy version but fails for reference.

        // Actually, we need the reference to PASS the test, so the rule must be something reference satisfies.
        // Let's invert: The rule is "if accounts.length != ids.length, balanceOfBatch reverts".
        // Reference satisfies this; buggy version does not (because it doesn't revert).

        // We can test this by checking that the low-level call reverts.
        assertTrue(refReverted, "balanceOfBatch should revert when lengths differ");
    }
}

