contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address admin, bool access) public {
        vm.assume(admin != address(this));
        uint256 tokenId = 0;
        uint256 before = c.getAllowanceRemaining(admin, tokenId);
        c.adjustAdminAccess(admin, access);
        uint256 after = c.getAllowanceRemaining(admin, tokenId);
